function header(){return `<header class="site-header"><div class="container header-row"><a class="brand" href="#/" aria-label="NegosyoDepot home"><span class="brand-mark">N</span><span class="brand-name">negosyo<span>depot</span></span></a><button class="icon-btn" id="menuToggle" aria-label="Open menu">☰</button><nav class="nav" id="nav">${link("/explore","Explore businesses")}${link("/grow","Grow & expand")}${link("/fulfillment","Fulfillment")}${link("/partners","Partners")}${link("/membership","Membership")}${link("/resources","Resources")}</nav><div class="header-actions">${link("/ai","✦ Ask AI","btn btn-outline")}${link("/login","Sign in","btn btn-primary")}</div></div></header>`}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-grid"><div class="footer-brand"><a class="brand" href="#/"><span class="brand-mark">N</span><span class="brand-name">negosyo<span>depot</span></span></a><p>Where Filipinos find a business they can start, buy, operate, and grow—with the FLAME PH ecosystem behind them.</p><span class="status-pill">Business Engine · FLAME PH</span></div><div><h4>Explore</h4>${link("/explore","Find a negosyo")}${link("/find","Business finder")}${link("/compare","Compare opportunities")}${link("/fulfillment","Fulfillment network")}</div><div><h4>Grow</h4>${link("/grow","Grow locally")}${link("/scale","Scale globally")}${link("/post","Post your business")}${link("/partners","Corporate partners")}</div><div><h4>About</h4>${link("/ecosystem","FLAME PH ecosystem")}${link("/resources","Resources")}${link("/trust","Trust & safety")}${link("/contact","Contact us")}</div></div><div class="footer-bottom"><span>© 2026 NegosyoDepot · A FLAME PH MSME ecosystem platform</span><span>${link("/privacy","Privacy")}${link("/terms","Terms")}</span></div></div></footer><section class="construction" aria-label="MarketplacePH announcement"><div class="container construction-row"><p><strong>We're still under construction.</strong> MarketplacePH is a work in progress. Sign up now to get updates and new features as soon as they are ready.</p><a class="btn" href="https://www.marketplaceph.com/login"><strong>Sign up free</strong></a></div></section>`}
